      }
    },
    {
      "title": "A threshold is a cutoff in z",
      "narration": "The horizontal line marks a probability cutoff; where it meets the curve defines z*. At 0.5 the cutoff sits at z* = 0 — the natural, symmetric decision boundary.",
      "state": {
        "threshold": 0.5,
        "decisionRegions": "on"
      }
    },
    {
      "title": "Raising the bar",
      "narration": "Demand 90% confidence and z* slides far to the right: far fewer inputs are classified as class 1. Lower the threshold and the boundary slides left.",
      "state": {
