// @FIGURE_CODE_BEGIN
const SERIF = "Georgia,'Times New Roman',Times,serif";
const C_ORANGE = '#d9795a';
const C_BLUE = '#4a6fa5';
const C_GUIDE = '#bdbdbd';
const TARGET_AR = 1.45;   /* plot-area width / height, matching the source figure */

function sigmoid(z) { return 1 / (1 + Math.exp(-z)); }
function logitOf(p) { return Math.log(p / (1 - p)); }
function clampN(v, lo, hi) { return Math.min(hi, Math.max(lo, v)); }

const figState = {
  threshold: 0.5,
  regions: false,
  showThreshold: false,
  markerZ: 0,
  showMarker: false,
  showReadout: false
};

const figCanvas = document.createElement('canvas');
figCanvas.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(figCanvas);

const curvePts = [];
for (let i = 0; i <= 400; i++) { const z = -5 + 10 * i / 400; curvePts.push({ x: z, y: sigmoid(z) }); }

function fontOf(chart) { return chart.$f || Math.max(10, Math.min(24, Math.min(chart.width, chart.height) * 0.055)); }
function baseS(chart) {
  const a = chart.chartArea;
  if (!a) return Math.min(chart.width, chart.height);
  return Math.min(a.right - a.left, a.bottom - a.top);
}

/* ---------- text helpers ---------- */
function runsWidth(ctx, runs, size) {
  let w = 0;
  for (const r of runs) { ctx.font = (r[1] ? 'italic ' : '') + size + 'px ' + SERIF; w += ctx.measureText(r[0]).width; }
  return w;
}
function drawRuns(ctx, runs, x, y, size, color, halo) {
  let cx = x;
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  for (const r of runs) {
    ctx.font = (r[1] ? 'italic ' : '') + size + 'px ' + SERIF;
    if (halo) { ctx.lineJoin = 'round'; ctx.lineWidth = Math.max(2, size * 0.3); ctx.strokeStyle = '#fff'; ctx.strokeText(r[0], cx, y); }
    ctx.fillStyle = color; ctx.fillText(r[0], cx, y);
    cx += ctx.measureText(r[0]).width;
  }
  return cx - x;
}
function haloText(ctx, txt, x, y, size, color, align) {
  ctx.font = size + 'px ' + SERIF;
  ctx.textAlign = align || 'left';
  ctx.textBaseline = 'alphabetic';
  ctx.lineJoin = 'round'; ctx.lineWidth = Math.max(2, size * 0.32); ctx.strokeStyle = '#fff';
  ctx.strokeText(txt, x, y);
  ctx.fillStyle = color; ctx.fillText(txt, x, y);
}

/* ---------- background layer ---------- */
const bgPlugin = {
  id: 'figBg',
  beforeDatasetsDraw(chart) {
    const a = chart.chartArea; if (!a) return;
    const ctx = chart.ctx, x = chart.scales.x, y = chart.scales.y, S = baseS(chart);
    ctx.save();
    ctx.beginPath(); ctx.rect(a.left, a.top, a.right - a.left, a.bottom - a.top); ctx.clip();

    if (figState.regions) {
      const zs = clampN(logitOf(figState.threshold), -5, 5);
      const px = x.getPixelForValue(zs);
      ctx.fillStyle = 'rgba(74,111,165,0.10)';
      ctx.fillRect(a.left, a.top, px - a.left, a.bottom - a.top);
      ctx.fillStyle = 'rgba(217,121,86,0.12)';
      ctx.fillRect(px, a.top, a.right - px, a.bottom - a.top);
    }

    /* dotted guides through (0, 0.5) — as in the source figure */
    ctx.setLineDash([1.6, 3.6]);
    ctx.lineWidth = Math.max(1, S * 0.0045);
    ctx.strokeStyle = C_GUIDE;
    const gx = x.getPixelForValue(0), gy = y.getPixelForValue(0.5);
    ctx.beginPath();
    ctx.moveTo(a.left, gy); ctx.lineTo(gx, gy);
    ctx.moveTo(gx, a.bottom); ctx.lineTo(gx, gy);
    ctx.stroke();

    if (figState.showThreshold) {
      const ty = y.getPixelForValue(figState.threshold);
      ctx.setLineDash([7, 5]);
      ctx.strokeStyle = C_BLUE;
      ctx.lineWidth = Math.max(1.4, S * 0.006);
      ctx.beginPath(); ctx.moveTo(a.left, ty); ctx.lineTo(a.right, ty); ctx.stroke();

      const zs = clampN(logitOf(figState.threshold), -5, 5);
      const px = x.getPixelForValue(zs);
      ctx.setLineDash([5, 4]);
      ctx.strokeStyle = '#7488a6';
      ctx.beginPath(); ctx.moveTo(px, ty); ctx.lineTo(px, a.bottom); ctx.stroke();
    }
    ctx.restore();
  }
};

/* ---------- foreground layer ---------- */
const fgPlugin = {
  id: 'figFg',
  afterDatasetsDraw(chart) {
    const a = chart.chartArea; if (!a) return;
    const ctx = chart.ctx, x = chart.scales.x, y = chart.scales.y;
    const S = baseS(chart), f = fontOf(chart);
    const W = a.right - a.left, H = a.bottom - a.top;
    ctx.save();

    /* tick marks (major at -5/0/5 and 0.0/1.0, minor elsewhere) */
    ctx.strokeStyle = '#222';
    ctx.lineWidth = Math.max(1, S * 0.005);
    ctx.setLineDash([]);
    for (let i = -5; i <= 5; i++) {
      const px = x.getPixelForValue(i);
      const L = (i === -5 || i === 0 || i === 5) ? S * 0.028 : S * 0.015;
      ctx.beginPath(); ctx.moveTo(px, a.bottom); ctx.lineTo(px, a.bottom + L); ctx.stroke();
    }
    for (let i = 0; i <= 10; i++) {
      const v = i / 10, py = y.getPixelForValue(v);
      const L = (i === 0 || i === 10) ? S * 0.028 : S * 0.015;
      ctx.beginPath(); ctx.moveTo(a.left, py); ctx.lineTo(a.left - L, py); ctx.stroke();
    }

    /* heavy black frame */
    ctx.strokeStyle = '#000';
    ctx.lineWidth = Math.max(1.6, S * 0.0075);
    ctx.strokeRect(a.left, a.top, W, H);

    /* axis titles, drawn manually so 'z' can be italic and large */
    const tf = f * 1.55;
    const xRuns = [['z', true]];
    const wx = runsWidth(ctx, xRuns, tf);
    drawRuns(ctx, xRuns, a.left + W / 2 - wx / 2, a.bottom + f * 3.15 + tf * 0.1, tf, '#000', false);

    const yRuns = [['sig[', false], ['z', true], [']', false]];
    const wy = runsWidth(ctx, yRuns, tf);
    ctx.save();
    ctx.translate(a.left - f * 3.1, a.top + H / 2);
    ctx.rotate(-Math.PI / 2);
    drawRuns(ctx, yRuns, -wy / 2, 0, tf, '#000', false);
    ctx.restore();

    /* formula 1 / (1 + exp[-z]) as a stacked fraction */
    const ff = f * 1.25;
    const den = [['1+exp[\u2212', false], ['z', true], [']', false]];
    const wDen = runsWidth(ctx, den, ff);
    const cx = a.left + W * 0.47;
    const ruleY = a.top + H * 0.155;
    ctx.font = ff + 'px ' + SERIF;
    const w1 = ctx.measureText('1').width;
    drawRuns(ctx, [['1', false]], cx - w1 / 2, ruleY - ff * 0.33, ff, '#111', true);
    drawRuns(ctx, den, cx - wDen / 2, ruleY + ff * 1.02, ff, '#111', true);
    ctx.strokeStyle = '#111';
    ctx.lineWidth = Math.max(1, ff * 0.065);
    ctx.beginPath();
    ctx.moveTo(cx - wDen / 2 - ff * 0.12, ruleY);
    ctx.lineTo(cx + wDen / 2 + ff * 0.12, ruleY);
    ctx.stroke();

    /* threshold annotations */
    if (figState.showThreshold) {
      const ty = y.getPixelForValue(figState.threshold);
      const zs = clampN(logitOf(figState.threshold), -5, 5);
      const px = x.getPixelForValue(zs);
      const lf = f * 0.82;
      const onLeft = zs > 0;
      haloText(ctx, 'threshold = ' + figState.threshold.toFixed(2),
        onLeft ? a.left + S * 0.03 : a.right - S * 0.03,
        ty - S * 0.028, lf, C_BLUE, onLeft ? 'left' : 'right');
      const zr = [['z', true], ['* = ' + zs.toFixed(2), false]];
      const wz = runsWidth(ctx, zr, lf);
      let zx = px + S * 0.025;
      if (zx + wz > a.right - S * 0.02) zx = px - S * 0.025 - wz;
      drawRuns(ctx, zr, zx, a.bottom - S * 0.035, lf, '#54657f', true);
    }

    /* decision-region legends, placed away from the curve */
    if (figState.regions) {
      const lf = f * 0.85;
      const zs = clampN(logitOf(figState.threshold), -5, 5);
      const mL = (-5 + zs) / 2, mR = (zs + 5) / 2;
      const yL = clampN(sigmoid(mL) + 0.34, 0.12, 0.88);
      const yR = clampN(sigmoid(mR) - 0.34, 0.12, 0.88);
      if (px1(x, zs) - a.left > lf * 4.5)
        haloText(ctx, 'predict 0', x.getPixelForValue(mL), y.getPixelForValue(yL), lf, '#3f6394', 'center');
      if (a.right - px1(x, zs) > lf * 4.5)
        haloText(ctx, 'predict 1', x.getPixelForValue(mR), y.getPixelForValue(yR), lf, '#b4593a', 'center');
    }

    /* draggable marker (hidden in the default view) */
    if (figState.showMarker) {
      const mz = clampN(figState.markerZ, -5, 5), mp = sigmoid(mz);
      const dx = x.getPixelForValue(mz), dy = y.getPixelForValue(mp);
      const r = Math.max(3, S * 0.019);
      ctx.beginPath(); ctx.arc(dx, dy, r + Math.max(1.2, S * 0.005), 0, 6.2832);
      ctx.fillStyle = '#fff'; ctx.fill();
      ctx.beginPath(); ctx.arc(dx, dy, r, 0, 6.2832);
      ctx.fillStyle = C_ORANGE; ctx.fill();
      ctx.strokeStyle = '#a8543a'; ctx.lineWidth = Math.max(1, S * 0.003); ctx.stroke();

      if (figState.showReadout) {
        const rf = f * 0.82;
        const l1 = 'z = ' + mz.toFixed(2);
        const l2 = 'sig[z] = ' + mp.toFixed(3);
        ctx.font = rf + 'px ' + SERIF;
        const bw = Math.max(ctx.measureText(l1).width, ctx.measureText(l2).width) + rf * 0.9;
        const bh = rf * 2.8;
        let bx = dx + r + rf * 0.6, by = dy + r + rf * 0.4;
        if (bx + bw > a.right - 4) bx = dx - r - rf * 0.6 - bw;
        if (by + bh > a.bottom - 4) by = dy - r - rf * 0.4 - bh;
        bx = clampN(bx, a.left + 3, a.right - bw - 3);
        by = clampN(by, a.top + 3, a.bottom - bh - 3);
        ctx.fillStyle = 'rgba(255,255,255,0.94)';
        ctx.strokeStyle = C_ORANGE; ctx.lineWidth = 1;
        ctx.beginPath();
        if (ctx.roundRect) { ctx.roundRect(bx, by, bw, bh, 4); } else { ctx.rect(bx, by, bw, bh); }
        ctx.fill(); ctx.stroke();
        haloText(ctx, l1, bx + rf * 0.45, by + rf * 1.18, rf, '#333', 'left');
        haloText(ctx, l2, bx + rf * 0.45, by + rf * 2.32, rf, '#333', 'left');
      }
    }
    ctx.restore();
  }
};
function px1(scale, v) { return scale.getPixelForValue(v); }

/* ---------- sizing: fonts, stroke width, and a source-matched aspect ---------- */
const sizePlugin = {
  id: 'figSizer',
  beforeLayout(chart) {
    const W = chart.width, H = chart.height;
    const f = Math.max(10, Math.min(26, Math.min(W * 0.75, H) * 0.062));
    chart.$f = f;
    chart.options.scales.x.ticks.font.size = f * 1.05;
    chart.options.scales.y.ticks.font.size = f * 1.05;

    /* space reserved by tick labels (chart) + manual axis titles */
    const tickLeft = f * 2.9, tickBottom = f * 2.2;
    let padL = f * 2.2, padR = f * 1.0, padT = f * 0.8, padB = f * 2.3;

    let availW = W - padL - padR - tickLeft;
    let availH = H - padT - padB - tickBottom;
    if (availW > 0 && availH > 0) {
      if (availW / availH > TARGET_AR) {
        const extra = availW - availH * TARGET_AR;
        padL += extra * 0.5; padR += extra * 0.5;
        availW -= extra;
      } else {
        const extra = availH - availW / TARGET_AR;
        padT += extra * 0.3; padB += extra * 0.7;
        availH -= extra;
      }
    }
    chart.options.layout.padding = { left: padL, right: padR, top: padT, bottom: padB };
    chart.data.datasets[0].borderWidth =
      Math.max(2, Math.min(9, Math.min(Math.max(availW, 1), Math.max(availH, 1)) * 0.014));
  }
};

const chart = new Chart(figCanvas.getContext('2d'), {
  type: 'line',
  data: {
    datasets: [{
      data: curvePts,
      borderColor: C_ORANGE,
      backgroundColor: 'transparent',
      borderWidth: 4,
      pointRadius: 0,
      pointHitRadius: 0,
      tension: 0,
      borderCapStyle: 'round',
      borderJoinStyle: 'round'
    }]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    events: [],
    layout: { padding: 12 },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: {
        type: 'linear', min: -5, max: 5,
        ticks: {
          stepSize: 5, autoSkip: false, padding: 10, maxRotation: 0,
          color: '#000', font: { size: 15, family: SERIF },
          callback: function (v) {
            if (Math.abs(v + 5) < 1e-6) return '-5.0';
            if (Math.abs(v) < 1e-6) return '0.0';
            if (Math.abs(v - 5) < 1e-6) return '5.0';
            return '';
          }
        },
        grid: { display: false, drawTicks: false, drawOnChartArea: false },
        border: { display: false },
        title: { display: false }
      },
      y: {
        type: 'linear', min: 0, max: 1,
        ticks: {
          stepSize: 1, autoSkip: false, padding: 10,
          color: '#000', font: { size: 15, family: SERIF },
          callback: function (v) {
            if (Math.abs(v) < 1e-6) return '0.0';
            if (Math.abs(v - 1) < 1e-6) return '1.0';
            return '';
          }
        },
        grid: { display: false, drawTicks: false, drawOnChartArea: false },
        border: { display: false },
        title: { display: false }
      }
    }
  },
  plugins: [sizePlugin, bgPlugin, fgPlugin]
});

window.__markRendered();

/* ---------- pointer interaction ---------- */
function figPos(e) {
  const r = figCanvas.getBoundingClientRect();
  return { x: e.clientX - r.left, y: e.clientY - r.top };
}
function inArea(p) {
  const a = chart.chartArea;
  return a && p.x >= a.left - 2 && p.x <= a.right + 2 && p.y >= a.top - 2 && p.y <= a.bottom + 2;
}
function setMarkerFromPixel(px) {
  figState.markerZ = clampN(chart.scales.x.getValueForPixel(px), -5, 5);
  figState.showMarker = true;
  figState.showReadout = true;
  chart.render();
}

let dragging = false, downX = 0, downY = 0, movedAmt = 0;

figCanvas.addEventListener('pointerdown', function (e) {
  const p = figPos(e);
  if (!inArea(p)) return;
  dragging = true; movedAmt = 0; downX = p.x; downY = p.y;
  try { figCanvas.setPointerCapture(e.pointerId); } catch (err) { }
  setMarkerFromPixel(p.x);
});

figCanvas.addEventListener('pointermove', function (e) {
  const p = figPos(e);
  if (dragging) {
    movedAmt = Math.max(movedAmt, Math.abs(p.x - downX) + Math.abs(p.y - downY));
    setMarkerFromPixel(p.x);
    return;
  }
  const a = chart.chartArea;
  if (!a || !inArea(p)) { hideTooltip(); figCanvas.style.cursor = 'default'; return; }
  const x = chart.scales.x, y = chart.scales.y;
  const dz = clampN(x.getValueForPixel(p.x), -5, 5);
  const curveY = y.getPixelForValue(sigmoid(dz));
  const tol = Math.max(7, baseS(chart) * 0.03);
  const mx = x.getPixelForValue(figState.markerZ), my = y.getPixelForValue(sigmoid(figState.markerZ));
  const dDot = figState.showMarker ? Math.hypot(p.x - mx, p.y - my) : 1e9;
  if (dDot < tol * 1.3) {
    figCanvas.style.cursor = 'grab';
    showTooltip('Drag me: z = ' + figState.markerZ.toFixed(2) + ' → sig[z] = ' + sigmoid(figState.markerZ).toFixed(3), e);
  } else if (Math.abs(p.y - curveY) < tol) {
    figCanvas.style.cursor = 'pointer';
    showTooltip('sig[' + dz.toFixed(2) + '] = ' + sigmoid(dz).toFixed(3), e);
  } else if (figState.showThreshold && Math.abs(p.y - y.getPixelForValue(figState.threshold)) < tol * 0.8) {
    figCanvas.style.cursor = 'pointer';
    showTooltip('Threshold ' + figState.threshold.toFixed(2) + '  ⇔  z* = ' + logitOf(figState.threshold).toFixed(2), e);
  } else {
    figCanvas.style.cursor = 'crosshair';
    hideTooltip();
  }
});

figCanvas.addEventListener('pointerup', function (e) {
  if (!dragging) return;
  dragging = false;
  if (movedAmt < 4) {
    const p = figPos(e);
    const y = chart.scales.y;
    if (figState.showThreshold && Math.abs(p.y - y.getPixelForValue(figState.threshold)) < Math.max(8, baseS(chart) * 0.03)) {
      showPopup('A probability cutoff is a cutoff in z',
        'Setting a probability threshold p* is the same as setting a score threshold z* = log[p*/(1−p*)]. Because the sigmoid is strictly increasing, "sig[z] ≥ p*" and "z ≥ z*" select exactly the same inputs. Moving the slider slides the vertical boundary along the z axis.');
    } else {
      showPopup('The logistic sigmoid',
        'sig[z] = 1/(1+exp[−z]) maps every real number into the open interval (0,1), so an unbounded score can be read as a probability. It is monotone, symmetric about (0, 0.5), and steepest at z = 0 — far from the origin huge changes in z barely move the output.');
    }
  }
});

figCanvas.addEventListener('pointerleave', function () { hideTooltip(); figCanvas.style.cursor = 'default'; });

document.addEventListener('fig-resize', function () { chart.resize(); });

/* ---------- control handlers ---------- */
function update_threshold(v) {
  figState.threshold = v;
  figState.showThreshold = true;
  const o = document.getElementById('thresholdVal');
  if (o) o.value = Number(v).toFixed(2);
  chart.render();
}
function toggle_decisionRegions(on) {
  figState.regions = on;
  if (on) figState.showThreshold = true;
  chart.render();
}
function trigger_reset() { applyStep(0); }

function setThresholdUI(v) {
  const i = document.getElementById('thresholdInput');
  if (i) i.value = v;
  const o = document.getElementById('thresholdVal');
  if (o) o.value = Number(v).toFixed(2);
  figState.threshold = +v;
}
function setRegionsUI(on) {
  const c = document.getElementById('decisionRegionsInput');
  if (c) c.checked = on;
  figState.regions = on;
}

/* ---------- demo step player ---------- */
const demoSteps = [
  {
    title: 'A curve with two ceilings',
    narration: 'The orange curve never touches 0 or 1 but approaches both. Drag inside the plot to place a marker and slide it toward either edge — large-magnitude scores barely change the probability.',
    apply: function () {
      setThresholdUI(0.5); setRegionsUI(false);
      figState.showThreshold = false;
      figState.markerZ = 0; figState.showMarker = false; figState.showReadout = false;
    }
  },
  {
    title: 'The centre point',
    narration: 'At z = 0 the sigmoid passes through exactly 0.5, where the curve is steepest. This is the point of maximum sensitivity: small changes in the score move the probability the most.',
    apply: function () {
      setThresholdUI(0.5); setRegionsUI(false);
      figState.showThreshold = false;
      figState.markerZ = 0; figState.showMarker = true; figState.showReadout = true;
    }
  },
  {
    title: 'A threshold is a cutoff in z',
    narration: 'The dashed line marks a probability cutoff; where it meets the curve defines z*. At 0.5 the cutoff sits at z* = 0 — the natural, symmetric decision boundary.',
    apply: function () {
      setThresholdUI(0.5); setRegionsUI(true);
      figState.showThreshold = true;
      figState.markerZ = 0; figState.showMarker = true; figState.showReadout = true;
    }
  },
  {
    title: 'Raising the bar',
    narration: 'Demand 90% confidence and z* slides far to the right: far fewer inputs are classified as class 1. Lower the threshold and the boundary slides left.',
    apply: function () {
      setThresholdUI(0.9); setRegionsUI(true);
      figState.showThreshold = true;
      figState.markerZ = logitOf(0.9); figState.showMarker = true; figState.showReadout = true;
    }
  },
  {
    title: 'Lowering the bar',
    narration: 'At a 0.2 threshold almost any mildly positive score is labelled class 1. The curve is unchanged — only where we cut it has moved.',
    apply: function () {
      setThresholdUI(0.2); setRegionsUI(true);
      figState.showThreshold = true;
      figState.markerZ = logitOf(0.2); figState.showMarker = true; figState.showReadout = true;
    }
  }
];

let stepIdx = 0;
function applyStep(i) {
  stepIdx = (i % demoSteps.length + demoSteps.length) % demoSteps.length;
  const s = demoSteps[stepIdx];
  s.apply();
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('stepLabel').textContent = 'step ' + (stepIdx + 1) + ' / ' + demoSteps.length;
  chart.render();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
